async function playlistFromLikes(pid=null){
 if(!me)return askLogin();await refreshLibrary();if(!pid&&!canCreatePlaylist())return;const existing=pid?await api('/api/playlists/'+pid):null,already=new Set(existing?.tracks.map(t=>t.id)||[]),choices=library.likes.filter(t=>!already.has(t.id));
 if(!choices.length){toast(existing?'추가할 좋아요 곡이 없어요. 먼저 음악에 좋아요를 눌러주세요.':'좋아하는 곡에 하트를 누르면 내 보관함에서 모아볼 수 있어요.');return;}
 dialog(`<h2>${existing?'좋아요한 곡 담기':'나만의 플레이리스트 만들기'}</h2><form id="likes-playlist-form">${existing?`<p>${esc(existing.playlist.name)}에 담을 곡을 선택하세요.</p>`:formField('플레이리스트 이름','name','text','','required maxlength="80" placeholder="예: 우울할 때, 기분 업, 밤 드라이브"')}<div class="picker-heading"><span>${choices.length}개의 좋아요한 곡</span><button type="button" class="text-link" id="pick-all-tracks">전체 선택</button></div><div class="likes-track-picker">${choices.map(t=>`<label class="likes-pick-row"><input type="checkbox" name="track_ids" value="${t.id}">${cover(t,'mini-cover')}<span><strong>${esc(t.title)}</strong><small>${esc(t.artist)}</small></span></label>`).join('')}</div>${existing?'':'<label class="checkbox-line"><input name="is_public" type="checkbox"> 다른 사람도 볼 수 있는 공개 플레이리스트</label>'}<button class="primary-button">${existing?'선택한 곡 담기':'만들고 곡 담기'}</button><p class="form-error" role="alert"></p></form>`);
 const form=$('#likes-playlist-form');$('#pick-all-tracks').onclick=()=>{const boxes=[...form.querySelectorAll('[name="track_ids"]')],all=boxes.every(x=>x.checked);boxes.forEach(x=>x.checked=!all);$('#pick-all-tracks').textContent=all?'전체 선택':'선택 해제';};
 form.onsubmit=busyForm(form,async fd=>{const ids=fd.getAll('track_ids');if(!ids.length)throw new Error('한 곡 이상 선택해주세요.');let target=pid;if(pid){for(const tid of ids)await api(`/api/playlists/${pid}/tracks/${tid}`,'PUT');}else target=(await api('/api/playlists','POST',{name:fd.get('name'),is_public:fd.has('is_public'),track_ids:ids})).id;$('#dialog').close();await refreshLibrary();if(location.hash==='#playlist/'+target)await render();else location.hash='playlist/'+target;toast('내 보관함에 플레이리스트를 저장했습니다.');});
}
